package com.storemate.backend.web;
import com.storemate.backend.domain.*;import org.junit.jupiter.api.Test;import java.time.*;import java.math.*;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class RemainingRulesTest {
 @Test void quietHoursAcrossMidnightRespectDeviceTimezone(){var p=new NotificationPreference(mock(Account.class));p.update(true,true,true,true,true,true,true,"23:00","08:00");ZoneId zone=ZoneId.of("Asia/Seoul");var now=ZonedDateTime.of(2026,11,25,0,30,0,0,zone);assertEquals(now.withHour(8).withMinute(0).withZoneSameInstant(ZoneId.systemDefault()).toLocalDateTime(),PushPolicy.quietEnd(p,now));assertNull(PushPolicy.quietEnd(p,now.withHour(12)));assertNull(PushPolicy.quietEnd(p,now.withHour(8).withMinute(0)));}
 @Test void daytimeQuietHoursHaveExactBoundaries(){var p=new NotificationPreference(mock(Account.class));p.update(true,true,true,true,true,true,true,"09:00","17:00");var now=ZonedDateTime.now().withHour(9).withMinute(0);assertNotNull(PushPolicy.quietEnd(p,now));assertNull(PushPolicy.quietEnd(p,now.withHour(17)));}
 @Test void disabledPushAndKindPreferencesAreEnforced(){var p=new NotificationPreference(mock(Account.class));p.update(true,false,true,true,false,true,false,"23:00","08:00");assertFalse(PushPolicy.allowed(p,"task"));assertFalse(PushPolicy.allowed(p,"handover"));assertTrue(PushPolicy.allowed(p,"pay"));p.update(false,true,true,true,true,true,false,"23:00","08:00");assertFalse(PushPolicy.allowed(p,"receipt"));}
 @Test void ocrOnlyReturnsRealDatesAndRemovesDuplicates(){assertEquals(java.util.List.of("2026-11-25","2027-01-02"),ExpiryOcrController.dates("제조 2026.11.25 유통 2027년 1월 2일 / 2026-11-25 / 2026.02.30"));assertTrue(ExpiryOcrController.dates("1234567890123").isEmpty());assertEquals(java.util.List.of("2026-12-31"),ExpiryOcrController.dates("20261231"));}
 @Test void overnightScheduledShiftEndsNextDay(){var m=mock(StoreMember.class);var s=new WorkShift(m,LocalDate.of(2026,11,24),"22:00","06:00");assertEquals(LocalDateTime.of(2026,11,25,6,0),AttendanceAutomation.scheduledEnd(s));}
 @Test void allowanceCalculatesOnlyTheExplicitMultiplier(){var r=new PayrollController.Add("OVERTIME","확인한 가산분",null,new BigDecimal("2.5"),12000,new BigDecimal("0.5"),null);assertEquals(15000,PayrollController.calculate(r));}
 @Test void payrollRejectsAmbiguousAndUnboundedNumbers(){assertThrows(ApiException.class,()->PayrollController.calculate(new PayrollController.Add("OTHER","사유",100L,BigDecimal.ONE,12000,BigDecimal.ONE,null)));assertThrows(ApiException.class,()->PayrollController.calculate(new PayrollController.Add("OTHER","사유",null,new BigDecimal("745"),12000,BigDecimal.ONE,null)));}
}
